// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 seed) public {
        // Bound seed to a reasonable value for marketDrugs
        uint256 drugs = bound(seed, 1, 1e18);
        // Ensure caller is not address(0) since transfer to ceoAddress might fail otherwise
        vm.assume(caller != address(0));
        vm.assume(caller != c.ceoAddress()); // ceoAddress is set in constructor; keep it as is

        // Seed market first: need to call seedMarket via ceoAddress
        vm.prank(c.ceoAddress());
        c.seedMarket(drugs);

        // Now call getFreeKilo as caller
        vm.prank(caller);
        c.getFreeKilo();

        // Record block.timestamp after the call
        uint256 timestampAfterCall = block.timestamp;

        // Now call DrugDealer() as ceoAddress (only person allowed) to trigger the bug difference
        vm.prank(c.ceoAddress());
        c.DrugDealer();

        // Read lastCollect for caller after DrugDealer()
        uint256 lastCollectCaller = c.lastCollect(caller);

        // The rule: lastCollect[caller] should equal block.timestamp (or block.timestamp-1) at time of getFreeKilo call.
        // Since block.timestamp may advance during DrugDealer(), we check that lastCollectCaller is either timestampAfterCall or timestampAfterCall - 1.
        // In reference C, it's exactly timestampAfterCall. In mutant, it's timestampAfterCall - 1.
        // So we assert equality to timestampAfterCall (will pass on reference, fail on mutant).
        assertTrue(lastCollectCaller == timestampAfterCall);
    }
}

